function sumOddLengthSubarrays(arr: number[]): number {
    const n = arr.length;
    let sum = 0;
    for (let i = 0; i < n; i++) {
        // Number of subarrays containing index i:
        // (i + 1) choices for the left endpoint, (n - i) for the right endpoint.
        const total = (i + 1) * (n - i);
        // Of those, the count of odd-length subarrays is ceil(total / 2).
        const oddCount = Math.floor((total + 1) / 2);
        sum += arr[i] * oddCount;
    }
    return sum;
}

